#include <stdint.h>
#include <stddef.h>
#include <stdio.h>

/* generated by ICDeCompiler */
void rescale_test(int32_t acc[1][8][4], int8_t out[1][8][4]);

/* reference: the same requantization TFLite performs */
static int8_t ref_requant(int32_t acc, int32_t m0, int shift, int out_zp)
{
    int64_t prod = (int64_t)acc * (int64_t)m0;
    int64_t half = 1LL << (shift - 1);
    int64_t nudge = acc >= 0 ? half : -half;
    int64_t v = (prod + nudge) >> shift;
    int32_t r = (int32_t)v + out_zp;
    if (r > 127) r = 127;
    if (r < -128) r = -128;
    return (int8_t)r;
}

int main(void)
{
    int32_t acc[1][8][4];
    int8_t out[1][8][4];
    int8_t ref[8][4];

    /* spread of values including negatives and near-saturation */
    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 4; j++)
            acc[0][i][j] = (i - 4) * 100000 + j * 37000;

    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 4; j++)
            ref[i][j] = ref_requant(acc[0][i][j], 1112281741, 38, -128);

    rescale_test(acc, out);

    int bad = 0;
    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 4; j++)
            if (out[0][i][j] != ref[i][j]) {
                if (bad < 5)
                    printf("mismatch [%d][%d]: acc=%d got %d, expected %d\n",
                           i, j, acc[0][i][j], out[0][i][j], ref[i][j]);
                bad++;
            }

    if (bad == 0) {
        printf("OK: tosa.rescale matches reference requantization\n");
        return 0;
    }
    printf("FAIL: %d mismatches\n", bad);
    return 1;
}